1	<!DOCTYPE html>
2	<html lang="zh-CN">
3	<head>
4	    <meta charset="UTF-8">
5	    <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	    <title>Power 电源服务文件清单</title>
7	    <style>
8	        :root {
9	            --bg-primary: #0f0f14;
10	            --bg-secondary: #1a1a24;
11	            --bg-tertiary: #252532;
12	            --text-primary: #e8e8f0;
13	            --text-secondary: #a0a0b0;
14	            --text-muted: #707080;
15	            --accent: #7c6aff;
16	            --accent-hover: #9b8aff;
17	            --border: #303040;
18	            --core-color: #ff7b72;
19	            --supporting-color: #79c0ff;
20	            --success: #56d364;
21	            --warning: #e3b341;
22	        }
23	
24	        * {
25	            box-sizing: border-box;
26	            margin: 0;
27	            padding: 0;
28	        }
29	
30	        body {
31	            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
32	            background: var(--bg-primary);
33	            color: var(--text-primary);
34	            line-height: 1.6;
35	            padding: 20px;
36	            min-height: 100vh;
37	        }
38	
39	        .container {
40	            max-width: 1400px;
41	            margin: 0 auto;
42	        }
43	
44	        header {
45	            text-align: center;
46	            margin-bottom: 40px;
47	            padding: 30px;
48	            background: linear-gradient(135deg, var(--bg-secondary) 0%, var(--bg-tertiary) 100%);
49	            border-radius: 16px;
50	            border: 1px solid var(--border);
51	        }
52	
53	        h1 {
54	            font-size: 2.5rem;
55	            font-weight: 700;
56	            background: linear-gradient(135deg, var(--accent) 0%, var(--text-primary) 100%);
57	            -webkit-background-clip: text;
58	            -webkit-text-fill-color: transparent;
59	            background-clip: text;
60	            margin-bottom: 10px;
61	        }
62	
63	        .subtitle {
64	            color: var(--text-secondary);
65	            font-size: 1.1rem;
66	        }
67	
68	        .stats-grid {
69	            display: grid;
70	            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
71	            gap: 20px;
72	            margin-bottom: 30px;
73	        }
74	
75	        .stat-card {
76	            background: var(--bg-secondary);
77	            border: 1px solid var(--border);
78	            border-radius: 12px;
79	            padding: 20px;
80	            text-align: center;
81	        }
82	
83	        .stat-value {
84	            font-size: 2.5rem;
85	            font-weight: 700;
86	            color: var(--accent);
87	        }
88	
89	        .stat-label {
90	            color: var(--text-secondary);
91	            font-size: 0.9rem;
92	            margin-top: 5px;
93	        }
94	
95	        .legend {
96	            display: flex;
97	            gap: 30px;
98	            justify-content: center;
99	            margin-bottom: 20px;
100	            flex-wrap: wrap;
101	        }
102	
103	        .legend-item {
104	            display: flex;
105	            align-items: center;
106	            gap: 8px;
107	        }
108	
109	        .legend-badge {
110	            padding: 4px 12px;
111	            border-radius: 6px;
112	            font-size: 0.85rem;
113	            font-weight: 600;
114	        }
115	
116	        .legend-badge.core {
117	            background: rgba(255, 123, 114, 0.2);
118	            color: var(--core-color);
119	            border: 1px solid var(--core-color);
120	        }
121	
122	        .legend-badge.supporting {
123	            background: rgba(121, 192, 255, 0.2);
124	            color: var(--supporting-color);
125	            border: 1px solid var(--supporting-color);
126	        }
127	
128	        .table-container {
129	            background: var(--bg-secondary);
130	            border: 1px solid var(--border);
131	            border-radius: 12px;
132	            overflow: hidden;
133	        }
134	
135	        table {
136	            width: 100%;
137	            border-collapse: collapse;
138	        }
139	
140	        thead {
141	            background: var(--bg-tertiary);
142	        }
143	
144	        th {
145	            padding: 16px 20px;
146	            text-align: left;
147	            font-weight: 600;
148	            color: var(--text-secondary);
149	            border-bottom: 2px solid var(--border);
150	            position: sticky;
151	            top: 0;
152	        }
153	
154	        td {
155	            padding: 14px 20px;
156	            border-bottom: 1px solid var(--border);
157	            vertical-align: top;
158	        }
159	
160	        tr:hover {
161	            background: rgba(124, 106, 255, 0.05);
162	        }
163	
164	        tr:last-child td {
165	            border-bottom: none;
166	        }
167	
168	        .filename {
169	            font-family: "SF Mono", "Fira Code", "Consolas", monospace;
170	            font-size: 0.9rem;
171	            color: var(--accent);
172	            word-break: break-all;
173	        }
174	
175	        .class-name {
176	            font-family: "SF Mono", "Fira Code", "Consolas", monospace;
177	            font-size: 0.85rem;
178	            color: var(--success);
179	            background: rgba(86, 211, 100, 0.1);
180	            padding: 2px 8px;
181	            border-radius: 4px;
182	            display: inline-block;
183	        }
184	
185	        .responsibility {
186	            font-size: 0.9rem;
187	            color: var(--text-primary);
188	            max-width: 500px;
189	        }
190	
191	        .type-cell {
192	            text-align: center;
193	        }
194	
195	        .type-badge {
196	            padding: 4px 12px;
197	            border-radius: 6px;
198	            font-size: 0.8rem;
199	            font-weight: 600;
200	            display: inline-block;
201	            min-width: 80px;
202	        }
203	
204	        .type-badge.core {
205	            background: rgba(255, 123, 114, 0.2);
206	            color: var(--core-color);
207	        }
208	
209	        .type-badge.supporting {
210	            background: rgba(121, 192, 255, 0.2);
211	            color: var(--supporting-color);
212	        }
213	
214	        .section-header {
215	            background: var(--bg-tertiary);
216	            padding: 12px 20px;
217	            font-weight: 600;
218	            color: var(--text-secondary);
219	            border-bottom: 1px solid var(--border);
220	        }
221	
222	        .directory {
223	            font-size: 0.75rem;
224	            color: var(--text-muted);
225	            margin-top: 4px;
226	        }
227	
228	        footer {
229	            margin-top: 40px;
230	            padding: 20px;
231	            text-align: center;
232	            color: var(--text-muted);
233	            font-size: 0.85rem;
234	        }
235	
236	        @media (max-width: 768px) {
237	            h1 {
238	                font-size: 1.8rem;
239	            }
240	
241	            .stats-grid {
242	                grid-template-columns: repeat(2, 1fr);
243	            }
244	
245	            th, td {
246	                padding: 12px;
247	            }
248	
249	            .responsibility {
250	                max-width: 200px;
251	            }
252	        }
253	    </style>
254	</head>
255	<body>
256	    <div class="container">
257	        <header>
258	            <h1>Power 电源服务文件清单</h1>
259	            <p class="subtitle">/home/cwtrocks/aosp/base/services/core/java/com/android/server/power/</p>
260	        </header>
261	
262	        <div class="stats-grid">
263	            <div class="stat-card">
264	                <div class="stat-value">121</div>
265	                <div class="stat-label">Java 文件总数</div>
266	            </div>
267	            <div class="stat-card">
268	                <div class="stat-value">7</div>
269	                <div class="stat-label">核心类/接口</div>
270	            </div>
271	            <div class="stat-card">
272	                <div class="stat-value">114</div>
273	                <div class="stat-label">辅助类</div>
274	            </div>
275	            <div class="stat-card">
276	                <div class="stat-value">6</div>
277	                <div class="stat-label">子包数量</div>
278	            </div>
279	        </div>
280	
281	        <div class="legend">
282	            <div class="legend-item">
283	                <span class="legend-badge core">Core</span>
284	                <span>核心电源管理组件</span>
285	            </div>
286	            <div class="legend-item">
287	                <span class="legend-badge supporting">Supporting</span>
288	                <span>辅助/支持组件</span>
289	            </div>
290	        </div>
291	
292	        <div class="table-container">
293	            <table>
294	                <thead>
295	                    <tr>
296	                        <th>文件名</th>
297	                        <th>类/接口声明</th>
298	                        <th>核心职责</th>
299	                        <th class="type-cell">类型</th>
300	                    </tr>
301	                </thead>
302	                <tbody>
303	                    <!-- Core Files -->
304	                    <tr class="section-header">
305	                        <td colspan="4">=== 核心电源管理 (Core) ===</td>
306	                    </tr>
307	                    <tr>
308	                        <td>
309	                            <div class="filename">PowerManagerService.java</div>
310	                            <div class="directory">services/core/java/com/android/server/power/</div>
311	                        </td>
312	                        <td><span class="class-name">public final class PowerManagerService extends SystemService implements Watchdog.Monitor</span></td>
313	                        <td class="responsibility">主电源管理服务，协调设备电源管理功能。管理 Wake Lock、屏幕亮度、用户活动超时、睡眠/唤醒状态。是电源管理的核心入口点。</td>
314	                        <td class="type-cell"><span class="type-badge core">Core</span></td>
315	                    </tr>
316	                    <tr>
317	                        <td>
318	                            <div class="filename">Notifier.java</div>
319	                            <div class="directory">services/core/java/com/android/server/power/</div>
320	                        </td>
321	                        <td><span class="class-name">public class Notifier</span></td>
322	                        <td class="responsibility">电源状态变化广播通知器。向系统和应用发送屏幕开关、充电状态等重要电源事件通知。设计用于折叠不必要的广播。</td>
323	                        <td class="type-cell"><span class="type-badge core">Core</span></td>
324	                    </tr>
325	                    <tr>
326	                        <td>
327	                            <div class="filename">PowerGroup.java</div>
328	                            <div class="directory">services/core/java/com/android/server/power/</div>
329	                        </td>
330	                        <td><span class="class-name">public class PowerGroup</span></td>
331	                        <td class="responsibility">电源组管理，用于存储每个 DisplayGroup 的电源相关请求。支持多显示设备环境下的独立电源控制。</td>
332	                        <td class="type-cell"><span class="type-badge core">Core</span></td>
333	                    </tr>
334	                    <tr>
335	                        <td>
336	                            <div class="filename">SuspendBlocker.java</div>
337	                            <div class="directory">services/core/java/com/android/server/power/</div>
338	                        </td>
339	                        <td><span class="class-name">interface SuspendBlocker</span></td>
340	                        <td class="responsibility">底层 suspend blocker 接口，防止 CPU 进入睡眠。acquire/release 配对使用，支持嵌套。</td>
341	                        <td class="type-cell"><span class="type-badge core">Core</span></td>
342	                    </tr>
343	                    <tr>
344	                        <td>
345	                            <div class="filename">ScreenOnBlocker.java</div>
346	                            <div class="directory">services/core/java/com/android/server/power/</div>
347	                        </td>
348	                        <td><span class="class-name">interface ScreenOnBlocker</span></td>
349	                        <td class="responsibility">底层屏幕解锁阻止机制，在 WindowManager 准备好显示新内容前保持屏幕关闭或隐藏内容。</td>
350	                        <td class="type-cell"><span class="type-badge core">Core</span></td>
351	                    </tr>
352	                    <tr>
353	                        <td>
354	                            <div class="filename">ShutdownThread.java</div>
355	                            <div class="directory">services/core/java/com/android/server/power/</div>
356	                        </td>
357	                        <td><span class="class-name">public final class ShutdownThread extends Thread</span></td>
358	                        <td class="responsibility">关机执行线程，负责关闭设备、重启、进入恢复模式等操作。处理关机广播、停止服务、保存检查点等。</td>
359	                        <td class="type-cell"><span class="type-badge core">Core</span></td>
360	                    </tr>
361	                    <tr>
362	                        <td>
363	                            <div class="filename">PowerManagerShellCommand.java</div>
364	                            <div class="directory">services/core/java/com/android/server/power/</div>
365	                        </td>
366	                        <td><span class="class-name">class PowerManagerShellCommand extends ShellCommand</span></td>
367	                        <td class="responsibility">Shell 命令支持，提供 adb shell cmd power 子命令接口。用于调试和测试电源管理功能。</td>
368	                        <td class="type-cell"><span class="type-badge core">Core</span></td>
369	                    </tr>
370	
371	                    <!-- Supporting Files - Detection -->
372	                    <tr class="section-header">
373	                        <td colspan="4">=== 检测器/传感器 (Detection) ===</td>
374	                    </tr>
375	                    <tr>
376	                        <td>
377	                            <div class="filename">WirelessChargerDetector.java</div>
378	                            <div class="directory">services/core/java/com/android/server/power/</div>
379	                        </td>
380	                        <td><span class="class-name">public class WirelessChargerDetector</span></td>
381	                        <td class="responsibility">无线充电检测，使用重力传感器检测设备放置/拿起无线充电器。避免虚假信号触发。</td>
382	                        <td class="type-cell"><span class="type-badge supporting">Supporting</span></td>
383	                    </tr>
384	                    <tr>
385	                        <td>
386	                            <div class="filename">AttentionDetector.java</div>
387	                            <div class="directory">services/core/java/com/android/server/power/</div>
388	                        </td>
389	                        <td><span class="class-name">public class AttentionDetector</span></td>
390	                        <td class="responsibility">用户注意力检测，判断用户是否正在关注手机。在屏幕变暗前检查注意力，可延长屏幕超时。</td>
391	                        <td class="type-cell"><span class="type-badge supporting">Supporting</span></td>
392	                    </tr>
393	                    <tr>
394	                        <td>
395	                            <div class="filename">FaceDownDetector.java</div>
396	                            <div class="directory">services/core/java/com/android/server/power/</div>
397	                        </td>
398	                        <td><span class="class-name">public class FaceDownDetector implements SensorEventListener</span></td>
399	                        <td class="responsibility">面部朝下检测，实现 Flip to Screen Off 功能。检测手机是否被翻转扣下以自动关闭屏幕。</td>
400	                        <td class="type-cell"><span class="type-badge supporting">Supporting</span></td>
401	                    </tr>
402	                    <tr>
403	                        <td>
404	                            <div class="filename">ScreenUndimDetector.java</div>
405	                            <div class="directory">services/core/java/com/android/server/power/</div>
406	                        </td>
407	                        <td><span class="class-name">public class ScreenUndimDetector</span></td>
408	                        <td class="responsibility">屏幕取消变暗检测，检测用户手动调亮屏幕的次数。当检测到多次取消变暗时临时保持屏幕常亮。</td>
409	                        <td class="type-cell"><span class="type-badge supporting">Supporting</span></td>
410	                    </tr>
411	
412	                    <!-- Supporting Files - Power Saving -->
413	                    <tr class="section-header">
414	                        <td colspan="4">=== 电源节省/低功耗 (Power Saving) ===</td>
415	                    </tr>
416	                    <tr>
417	                        <td>
418	                            <div class="filename">LowPowerStandbyController.java</div>
419	                            <div class="directory">services/core/java/com/android/server/power/</div>
420	                        </td>
421	                        <td><span class="class-name">public class LowPowerStandbyController</span></td>
422	                        <td class="responsibility">低功耗待机控制器，管理设备进入极低功耗状态。限制后台网络活动、后台任务执行等。</td>
423	                        <td class="type-cell"><span class="type-badge supporting">Supporting</span></td>
424	                    </tr>
425	                    <tr>
426	                        <td>
427	                            <div class="filename">LowPowerStandbyControllerInternal.java</div>
428	                            <div class="directory">services/core/java/com/android/server/power/</div>
429	                        </td>
430	                        <td><span class="class-name">public abstract class LowPowerStandbyControllerInternal</span></td>
431	                        <td class="responsibility">低功耗待机内部接口，向上层服务暴露添加/移除白名单的功能。</td>
432	                        <td class="type-cell"><span class="type-badge supporting">Supporting</span></td>
433	                    </tr>
434	                    <tr>
435	                        <td>
436	                            <div class="filename">AmbientDisplaySuppressionController.java</div>
437	                            <div class="directory">services/core/java/com/android/server/power/</div>
438	                        </td>
439	                        <td><span class="class-name">public class AmbientDisplaySuppressionController</span></td>
440	                        <td class="responsibility">环境显示抑制控制器，与 SystemUI 通信以抑制/取消抑制常亮显示（AOD）。</td>
441	                        <td class="type-cell"><span class="type-badge supporting">Supporting</span></td>
442	                    </tr>
443	                    <tr>
444	                        <td>
445	                            <div class="filename">InattentiveSleepWarningController.java</div>
446	                            <div class="directory">services/core/java/com/android/server/power/</div>
447	                        </td>
448	                        <td><span class="class-name">public class InattentiveSleepWarningController</span></td>
449	                        <td class="responsibility">不注意睡眠警告控制器，与 SystemUI 通信显示/隐藏"未注意设备将进入睡眠"的警告叠加层。</td>
450	                        <td class="type-cell"><span class="type-badge supporting">Supporting</span></td>
451	                    </tr>
452	                    <tr>
453	                        <td>
454	                            <div class="filename">ScreenTimeoutOverridePolicy.java</div>
455	                            <div class="directory">services/core/java/com/android/server/power/</div>
456	                        </td>
457	                        <td><span class="class-name">final class ScreenTimeoutOverridePolicy</span></td>
458	                        <td class="responsibility">屏幕超时覆盖策略，处理屏幕超时覆盖 Wake Lock 的行为。定义释放原因代码和策略逻辑。</td>
459	                        <td class="type-cell"><span class="type-badge supporting">Supporting</span></td>
460	                    </tr>
461	
462	                    <!-- Supporting Files - Monitoring -->
463	                    <tr class="section-header">
464	                        <td colspan="4">=== 监控/日志 (Monitoring) ===</td>
465	                    </tr>
466	                    <tr>
467	                        <td>
468	                            <div class="filename">ThermalManagerService.java</div>
469	                            <div class="directory">services/core/java/com/android/server/power/</div>
470	                        </td>
471	                        <td><span class="class-name">public class ThermalManagerService extends SystemService</span></td>
472	                        <td class="responsibility">热管理服务，监听 HAL 热事件并分发给监听器。根据节流状态触发相应动作。</td>
473	                        <td class="type-cell"><span class="type-badge supporting">Supporting</span></td>
474	                    </tr>
475	                    <tr>
476	                        <td>
477	                            <div class="filename">WakefulnessSessionObserver.java</div>
478	                            <div class="directory">services/core/java/com/android/server/power/</div>
479	                        </td>
480	                        <td><span class="class-name">public class WakefulnessSessionObserver</span></td>
481	                        <td class="responsibility">唤醒会话观察者，跟踪设备的唤醒会话。记录唤醒原因和最后用户活动时间用于统计分析。</td>
482	                        <td class="type-cell"><span class="type-badge supporting">Supporting</span></td>
483	                    </tr>
484	                    <tr>
485	                        <td>
486	                            <div class="filename">WakeLockLog.java</div>
487	                            <div class="directory">services/core/java/com/android/server/power/</div>
488	                        </td>
489	                        <td><span class="class-name">final class WakeLockLog</span></td>
490	                        <td class="responsibility">Wake Lock 事件日志，使用预分配字节环形缓冲区优化内存使用。记录 Wake Lock 获取/释放事件。</td>
491	                        <td class="type-cell"><span class="type-badge supporting">Supporting</span></td>
492	                    </tr>
493	                    <tr>
494	                        <td>
495	                            <div class="filename">FrameworkStatsLogger.java</div>
496	                            <div class="directory">services/core/java/com/android/server/power/</div>
497	                        </td>
498	                        <td><span class="class-name">public class FrameworkStatsLogger</span></td>
499	                        <td class="responsibility">框架统计日志，记录 WakelockStateChanged push atom 到 statsd。</td>
500	                        <td class="type-cell"><span class="type-badge supporting">Supporting</span></td>
501	                    </tr>
502	                    <tr>
503	                        <td>
504	                            <div class="filename">ShutdownCheckPoints.java</div>
505	                            <div class="directory">services/core/java/com/android/server/power/</div>
506	                        </td>
507	                        <td><span class="class-name">public final class ShutdownCheckPoints</span></td>
508	                        <td class="responsibility">关机检查点记录，记录系统关机和重启方法调用的来源堆栈跟踪。用于调试关机问题。</td>
509	                        <td class="type-cell"><span class="type-badge supporting">Supporting</span></td>
510	                    </tr>
511	                    <tr>
512	                        <td>
513	                            <div class="filename">PreRebootLogger.java</div>
514	                            <div class="directory">services/core/java/com/android/server/power/</div>
515	                        </td>
516	                        <td><span class="class-name">final class PreRebootLogger</span></td>
517	                        <td class="responsibility">重启前日志工具，提供重启前信息的转储/清除功能。在特定条件下将调试信息保存到文件。</td>
518	                        <td class="type-cell"><span class="type-badge supporting">Supporting</span></td>
519	                    </tr>
520	
